R["hsgx-cp-m2-maxxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long best = 0;\n    for (int mask = 0; mask < (1 << n); ++mask) {\n        long long x = 0;\n        for (int i = 0; i < n; ++i) if (mask >> i & 1) x ^= a[i];\n        best = max(best, x);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgx-cp-m2-maxxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: greedy \"take it if the XOR grows\" (sorted descending). Fails\n    // the verified counterexample {8, 13, 6}: greedy returns 11, the true\n    // maximum is 14 (subset {8, 6}). The brute force over 2^n \u2264 2^20 is both\n    // simpler and correct \u2014 that is the entire lesson of the small-n law.\n    sort(a.begin(), a.end(), greater<long long>());\n    long long x = 0;\n    for (long long v : a) if ((x ^ v) > x) x ^= v;\n    out << x << \"\\n\";\n}\n";
R["hsgx-p3-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        cur = max(x, cur + x);\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgx-p3-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: \"max element times n\"? No \u2014 plausible wrong: best single element\n    // when all negative handled, but sum from global max to global min window\n    // ignoring order. Simpler classic wrong: take max prefix-suffix pair.\n    // Concretely: best = max(a) even when a full positive run beats it.\n    long long best = *max_element(a.begin(), a.end());\n    long long s = 0;\n    for (long long x : a) { s += x; best = max(best, s); }\n    // misses windows that start mid-array (resets never happen)\n    out << best << \"\\n\";\n}\n";
