R["hsgx-p4-loadsplit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long lo = *max_element(a.begin(), a.end());\n    long long hi = 0;\n    for (long long x : a) hi += x;\n    while (lo < hi) {\n        long long mid = (lo + hi) / 2;\n        long long need = 1, cur = 0;\n        for (long long x : a) {\n            if (cur + x > mid) { ++need; cur = x; }\n            else cur += x;\n        }\n        if (need <= k) hi = mid; else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}\n";
W["hsgx-p4-loadsplit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: greedy \"start a new chunk when the current chunk exceeds the\n    // average\" \u2014 the average is not the answer; deterministic wrong output.\n    long long tot = 0;\n    for (long long x : a) tot += x;\n    long long avg = tot / max(1, k);\n    long long need = 1, cur = 0, best = 0;\n    for (long long x : a) {\n        if (cur + x > avg) { best = max(best, cur); ++need; cur = x; }\n        else cur += x;\n    }\n    best = max(best, cur);\n    out << best << \"\\n\";\n}\n";
R["hsgx-p3-uniquelen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = (int)s.size();\n    vector<int> last(256, -1);\n    int best = 0, l = 0;\n    for (int r = 0; r < n; ++r) {\n        if (last[(unsigned char)s[r]] >= l) l = last[(unsigned char)s[r]] + 1;\n        last[(unsigned char)s[r]] = r;\n        best = max(best, r - l + 1);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgx-p3-uniquelen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    // WRONG: tracks the current run length, resetting only on ADJACENT\n    // repeats. Misses non-adjacent duplicates (\"abcabc\" has no adjacent\n    // repeat, so the run grows to 6 \u2014 but the true longest unique window\n    // is 3). Deterministic wrong on the classic test and on the big one.\n    int n = (int)s.size();\n    int len = 0, best = 0;\n    for (int r = 0; r < n; ++r) {\n        if (r > 0 && s[r] == s[r - 1]) len = 1;\n        else ++len;\n        best = max(best, len);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgx-p4-place"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long lo = 1, hi = a[n - 1] - a[0];\n    while (lo < hi) {\n        long long mid = (lo + hi + 1) / 2;\n        long long cnt = 1, last = a[0];\n        for (int i = 1; i < n && cnt < k; ++i) {\n            if (a[i] - last >= mid) { ++cnt; last = a[i]; }\n        }\n        if (cnt >= k) lo = mid; else hi = mid - 1;\n    }\n    out << lo << \"\\n\";\n}\n";
W["hsgx-p4-place"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    // WRONG: average-gap heuristic \u2014 place k points at equal average spacing.\n    // Deterministically wrong on clustered inputs.\n    long long span = a[n - 1] - a[0];\n    long long ans = span / max(1, k - 1);\n    out << ans << \"\\n\";\n}\n";
R["hsgx-p4-dominating"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> vals;\n    vals.reserve(2 * n);\n    for (long long x : a) { vals.push_back(x); vals.push_back(2 * x); }\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    auto rank = [&](long long v) {\n        return lower_bound(vals.begin(), vals.end(), v) - vals.begin() + 1;\n    };\n    int m = (int)vals.size();\n    vector<int> bit(m + 1, 0);\n    auto upd = [&](int i) { for (; i <= m; i += i & -i) bit[i]++; };\n    auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };\n    long long cnt = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        // inserted j > i: count values 2*a[j] strictly below a[i]\n        cnt += qry(rank(a[i]) - 1);\n        upd(rank(2 * a[i]));\n    }\n    out << cnt << \"\\n\";\n}\n";
W["hsgx-p4-dominating"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: O(n^2) nested scan \u2014 same answers, times out at n = 200000.\n    // The combination (compression + Fenwick) is the whole point.\n    long long cnt = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = i + 1; j < n; ++j)\n            if (a[i] > 2 * a[j]) ++cnt;\n    out << cnt << \"\\n\";\n}\n";
R["hsgx-p4-roads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> par(n + 1), sz(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    // iterative find (path halving)\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    int comp = n;\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        int ru = find(u), rv = find(v);\n        if (ru != rv) {\n            if (sz[ru] < sz[rv]) swap(ru, rv);\n            par[rv] = ru;\n            sz[ru] += sz[rv];\n            --comp;\n        }\n        out << comp << \"\\n\";\n    }\n}\n";
W["hsgx-p4-roads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    // WRONG: BFS the whole graph after each road \u2014 correct answers but\n    // O(n\u00b7m) \u2248 2\u00b710^10 at full scale; DSU over time is the point.\n    vector<vector<int>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n        vector<int> vis(n + 1, 0);\n        int comp = 0;\n        for (int s = 1; s <= n; ++s) {\n            if (vis[s]) continue;\n            ++comp;\n            vector<int> st = {s};\n            vis[s] = 1;\n            while (!st.empty()) {\n                int x = st.back(); st.pop_back();\n                for (int y : g[x]) if (!vis[y]) { vis[y] = 1; st.push_back(y); }\n            }\n        }\n        out << comp << \"\\n\";\n    }\n}\n";
R["hsgx-p4-parity"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<pair<int,int>>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v, w; in >> u >> v >> w;\n        g[u].push_back({v, w});\n        g[v].push_back({u, w});\n    }\n    // state: (vertex, parity of edges used). Min edges-walk with even count.\n    const long long INF = 1e18;\n    vector<vector<long long>> dist(n + 1, vector<long long>(2, INF));\n    priority_queue<tuple<long long,int,int>, vector<tuple<long long,int,int>>, greater<>> pq;\n    dist[1][0] = 0;\n    pq.push({0, 1, 0});\n    while (!pq.empty()) {\n        auto [d, u, p] = pq.top(); pq.pop();\n        if (d != dist[u][p]) continue;\n        for (auto [v, w] : g[u]) {\n            int np = p ^ 1;\n            if (d + w < dist[v][np]) {\n                dist[v][np] = d + w;\n                pq.push({d + w, v, np});\n            }\n        }\n    }\n    long long ans = dist[n][0];\n    out << (ans >= INF ? -1 : ans) << \"\\n\";\n}\n";
W["hsgx-p4-parity"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<pair<int,int>>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v, w; in >> u >> v >> w;\n        g[u].push_back({v, w});\n        g[v].push_back({u, w});\n    }\n    // WRONG: plain Dijkstra from 1 to n ignoring parity \u2014 the classic\n    // non-state solution. Fails whenever the shortest walk has odd length.\n    const long long INF = 1e18;\n    vector<long long> dist(n + 1, INF);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto [v, w] : g[u]) {\n            if (d + w < dist[v]) { dist[v] = d + w; pq.push({d + w, v}); }\n        }\n    }\n    out << (dist[n] >= INF ? -1 : dist[n]) << \"\\n\";\n}\n";
R["hsgx-p5-coins"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // Tarjan SCC (iterative)\n    vector<int> low(n + 1), num(n + 1, 0), comp(n + 1, -1);\n    vector<int> stk, path;\n    vector<vector<int>> chains(n + 1);\n    vector<size_t> it(n + 1, 0);\n    int timer = 0, ncomp = 0;\n    for (int s = 1; s <= n; ++s) {\n        if (num[s]) continue;\n        path.push_back(s);\n        while (!path.empty()) {\n            int u = path.back();\n            if (it[u] == 0) { num[u] = low[u] = ++timer; stk.push_back(u); }\n            bool advanced = false;\n            while (it[u] < g[u].size()) {\n                int v = g[u][it[u]++];\n                if (!num[v]) { chains[u].push_back(v); path.push_back(v); advanced = true; break; }\n                else if (comp[v] < 0) low[u] = min(low[u], num[v]);\n            }\n            if (!advanced) {\n                if (low[u] == num[u]) {\n                    ++ncomp;\n                    while (true) {\n                        int v = stk.back(); stk.pop_back();\n                        comp[v] = ncomp;\n                        if (v == u) break;\n                    }\n                }\n                path.pop_back();\n                if (!path.empty()) {\n                    int p = path.back();\n                    low[p] = min(low[p], low[u]);\n                }\n            }\n        }\n    }\n    // condensation: total coins per comp + best DP in reverse topo (comp ids\n    // from Tarjan are already reverse-topological: edges go comp[u] -> comp[v]\n    // with comp[u] >= comp[v]... actually Tarjan numbers comps in reverse\n    // topological order of the condensation, so DP by increasing comp id over\n    // reversed edges)\n    vector<long long> tot(ncomp + 1, 0);\n    for (int v = 1; v <= n; ++v) tot[comp[v]] += coin[v];\n    vector<long long> best(ncomp + 1, 0);\n    vector<vector<int>> radj(ncomp + 1);\n    for (int u = 1; u <= n; ++u)\n        for (int v : g[u])\n            if (comp[u] != comp[v]) radj[comp[v]].push_back(comp[u]);\n    long long ans = 0;\n    // Tarjan numbers components in REVERSE topological order of the\n    // condensation (sinks get small ids). Edges go comp[u] -> comp[v] with\n    // comp[u] > comp[v] for distinct comps, so predecessors have HIGHER ids:\n    // DP must run by DESCENDING component id.\n    for (int c = ncomp; c >= 1; --c) {\n        best[c] = tot[c];\n        for (int p : radj[c]) best[c] = max(best[c], tot[c] + best[p]);\n        ans = max(ans, best[c]);\n    }\n    out << ans << \"\\n\";\n}\n";
W["hsgx-p5-coins"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // WRONG: longest-path DP on the raw graph assuming it is a DAG \u2014\n    // visits nodes multiple times / cycles inflate the count. The tests\n    // include cycles whose coins would be double-counted.\n    const long long NEG = -1e18;\n    vector<long long> best(n + 1, NEG);\n    // naive DFS without cycle handling, memoized as if DAG\n    vector<long long> memo(n + 1, -1);\n    function<long long(int)> dfs = [&](int u) -> long long {\n        if (memo[u] != -1) return memo[u];\n        long long r = coin[u];\n        for (int v : g[u]) r = max(r, coin[u] + dfs(v));\n        return memo[u] = r;\n    };\n    long long ans = 0;\n    for (int s = 1; s <= n; ++s) ans = max(ans, dfs(s));\n    out << ans << \"\\n\";\n}\n";
