R["hsgx-p5-c9-trapping"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (auto& x : h) in >> x;\n    // water trapped between bars, classic two-pointer\n    long long l = 0, r = n - 1, lmax = 0, rmax = 0, water = 0;\n    while (l < r) {\n        if (h[l] < h[r]) {\n            lmax = max(lmax, h[l]);\n            water += lmax - h[l];\n            ++l;\n        } else {\n            rmax = max(rmax, h[r]);\n            water += rmax - h[r];\n            --r;\n        }\n    }\n    out << water << \"\\n\";\n}\n";
W["hsgx-p5-c9-trapping"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (auto& x : h) in >> x;\n    // BUG: water above each bar = min(maxL, maxR) - h[i], but the buggy\n    // version uses running max ONLY from the left (ignores the right wall)\n    long long runmax = 0, water = 0;\n    for (int i = 0; i < n; ++i) {\n        runmax = max(runmax, h[i]);\n        water += runmax - h[i];\n    }\n    out << water << \"\\n\";\n}\n";
