R["hsgx-cp-m1-rangesum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> a(n + 1, 0);\n    for (int i = 1; i <= n; ++i) { in >> a[i]; a[i] += a[i - 1]; }\n    long long X = 0, S = 0;\n    for (int t = 0; t < q; ++t) {\n        int l, r; in >> l >> r;\n        if (l > r) swap(l, r);\n        long long s = a[r] - a[l - 1];\n        out << s << \"\\n\";\n        if (q == 200000) {           // checksum protocol: only the full-scale\n            X ^= s;                  // test reports the folded pair \"X S\"\n            S = (S + s % 1000000007 + 1000000007) % 1000000007;\n        }\n    }\n    if (q == 200000) out << X << \" \" << S << \"\\n\";\n}\n";
W["hsgx-cp-m1-rangesum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    // WRONG: recomputes each query in O(r-l+1). With n,q = 200000 and ranges\n    // ~n/3 wide on average, that is ~10^10+ operations \u2014 far beyond the\n    // limit. The constraints name the tool: prefix sums, O(n + q).\n    for (int t = 0; t < q; ++t) {\n        int l, r; in >> l >> r;\n        if (l > r) swap(l, r);\n        long long s = 0;\n        for (int i = l; i <= r; ++i) s += a[i];\n        out << s << \"\\n\";\n        if (q == 200000) {\n            long long X = 0, S = 0;\n            X ^= s;\n            S = (S + s % 1000000007 + 1000000007) % 1000000007;\n        }\n    }\n}\n";
