R["hsgx-p5-c3-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long W; in >> n >> W;\n    vector<long long> dp(W + 1, 0);\n    for (int i = 0; i < n; ++i) {\n        long long w, val; in >> w >> val;\n        for (long long c = W; c >= w; --c)      // 0/1: iterate DOWN\n            dp[c] = max(dp[c], dp[c - w] + val);\n    }\n    out << dp[W] << \"\\n\";\n}\n";
W["hsgx-p5-c3-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long W; in >> n >> W;\n    vector<long long> dp(W + 1, 0);\n    for (int i = 0; i < n; ++i) {\n        long long w, val; in >> w >> val;\n        // BUG: forward capacity loop lets item i be used twice (class 3)\n        for (long long c = w; c <= W; ++c)\n            dp[c] = max(dp[c], dp[c - w] + val);\n    }\n    out << dp[W] << \"\\n\";\n}\n";
R["hsgx-p5-c4-prefix"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> a(n + 1, 0);\n    for (int i = 1; i <= n; ++i) { long long x; in >> x; a[i] = a[i - 1] + x; }\n    while (q--) {\n        int l, r; in >> l >> r;\n        out << a[r] - a[l - 1] << \"\\n\";\n    }\n}\n";
