W["hsgx-cp-m5-intervals"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& p : v) in >> p.first >> p.second;   // (start, end)\n    // WRONG: greedy by START (and relaxed s >= lastEnd) \u2014 fails both the\n    // adversarial ordering and the touching-endpoints convention.\n    sort(v.begin(), v.end());\n    long long cnt = 0, lastEnd = -4e18;\n    for (auto [s, e] : v) {\n        if (s >= lastEnd) { ++cnt; lastEnd = e; }\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsgx-p6-s1-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // Harness: Kadane (candidate) vs O(n^2) brute (oracle).\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(12345);\n    auto kadane = [&](const vector<long long>& v) {\n        long long best = LLONG_MIN, cur = 0;\n        for (long long x : v) { cur = max(x, cur + x); best = max(best, cur); }\n        return best;\n    };\n    auto brute = [&](const vector<long long>& v) {\n        long long best = LLONG_MIN;\n        for (size_t i = 0; i < v.size(); ++i) {\n            long long s = 0;\n            for (size_t j = i; j < v.size(); ++j) { s += v[j]; best = max(best, s); }\n        }\n        return best;\n    };\n    const int TRIALS = 3000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = 1 + (int)(rng() % 9);\n        vector<long long> v(len);\n        int mode = (int)(rng() % 4);\n        for (auto& x : v) {\n            if (mode == 0) x = (long long)(rng() % 11) - 5;         // small mix\n            else if (mode == 1) x = -(long long)(rng() % 5);        // non-positive\n            else if (mode == 2) x = (long long)(rng() % 2) * 6 - 3; // two values\n            else x = (long long)(rng() % 7) - 3;                    // uniform\n        }\n        if (kadane(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
W["hsgx-p6-s1-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // WRONG candidate: resets cur whenever it dips negative \u2014 but forgets\n    // the all-negative case handling the oracle catches (subtle: best is\n    // initialized to 0 instead of the first element).\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(12345);\n    auto cand = [&](const vector<long long>& v) {\n        long long best = 0, cur = 0;              // BUG: 0 initial best\n        for (long long x : v) { cur = max(x, cur + x); best = max(best, cur); }\n        return best;\n    };\n    auto brute = [&](const vector<long long>& v) {\n        long long best = LLONG_MIN;\n        for (size_t i = 0; i < v.size(); ++i) {\n            long long s = 0;\n            for (size_t j = i; j < v.size(); ++j) { s += v[j]; best = max(best, s); }\n        }\n        return best;\n    };\n    const int TRIALS = 3000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = 1 + (int)(rng() % 9);\n        vector<long long> v(len);\n        int mode = (int)(rng() % 4);\n        for (auto& x : v) {\n            if (mode == 0) x = (long long)(rng() % 11) - 5;\n            else if (mode == 1) x = -(long long)(rng() % 5);\n            else if (mode == 2) x = (long long)(rng() % 2) * 6 - 3;\n            else x = (long long)(rng() % 7) - 3;\n        }\n        if (cand(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
R["hsgx-p6-s2-removeone"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // Harness: \"can delete at most one element to make sorted?\" candidate\n    // (linear scan) vs brute (try deleting each index).\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(777);\n    auto cand = [](const vector<int>& v) {\n        int bad = -1;\n        for (size_t i = 1; i < v.size(); ++i) {\n            if (v[i - 1] > v[i]) { if (bad != -1) return false; bad = (int)i; }\n        }\n        if (bad == -1) return true;\n        auto w = v; w.erase(w.begin() + bad);\n        for (size_t i = 1; i < w.size(); ++i) if (w[i - 1] > w[i]) return false;\n        // also try deleting the left element of the violation\n        auto w2 = v; w2.erase(w2.begin() + bad - 1);\n        for (size_t i = 1; i < w2.size(); ++i) if (w2[i - 1] > w2[i]) return false;\n        return true;\n    };\n    auto brute = [](const vector<int>& v) {\n        if (v.size() <= 1) return true;\n        for (size_t d = 0; d < v.size(); ++d) {\n            vector<int> w;\n            for (size_t i = 0; i < v.size(); ++i) if (i != d) w.push_back(v[i]);\n            bool ok = true;\n            for (size_t i = 1; i < w.size(); ++i) if (w[i - 1] > w[i]) { ok = false; break; }\n            if (ok) return true;\n        }\n        return false;\n    };\n    const int TRIALS = 4000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = (int)(rng() % 8);\n        vector<int> v(len);\n        for (auto& x : v) x = (int)(rng() % 5);   // heavy ties: tie bugs surface\n        if (cand(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
W["hsgx-p6-s2-removeone"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // WRONG candidate: counts violations; assumes one violation is always\n    // fixable (ignores which side to delete and second violations).\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(777);\n    auto cand = [](const vector<int>& v) {\n        int bad = 0;\n        for (size_t i = 1; i < v.size(); ++i) if (v[i - 1] > v[i]) ++bad;\n        return bad <= 1;\n    };\n    auto brute = [](const vector<int>& v) {\n        if (v.size() <= 1) return true;\n        for (size_t d = 0; d < v.size(); ++d) {\n            vector<int> w;\n            for (size_t i = 0; i < v.size(); ++i) if (i != d) w.push_back(v[i]);\n            bool ok = true;\n            for (size_t i = 1; i < w.size(); ++i) if (w[i - 1] > w[i]) { ok = false; break; }\n            if (ok) return true;\n        }\n        return false;\n    };\n    const int TRIALS = 4000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = (int)(rng() % 8);\n        vector<int> v(len);\n        for (auto& x : v) x = (int)(rng() % 5);\n        if (cand(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
R["hsgx-p6-s3-majority"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // Harness: majority element (candidate: Boyer-Moore with verification)\n    // vs brute (count each value).\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(2024);\n    auto cand = [](const vector<int>& v) {\n        // Boyer-Moore + verify; returns element or -1 (no strict majority)\n        int c = 0; int cand2 = 0;\n        for (int x : v) { if (c == 0) cand2 = x; c += (x == cand2) ? 1 : -1; }\n        int cnt = 0;\n        for (int x : v) if (x == cand2) ++cnt;\n        return (2 * cnt > (int)v.size()) ? cand2 : -1;\n    };\n    auto brute = [](const vector<int>& v) {\n        for (int x : v) {\n            int cnt = 0;\n            for (int y : v) if (y == x) ++cnt;\n            if (2 * cnt > (int)v.size()) return x;\n        }\n        return -1;\n    };\n    const int TRIALS = 4000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = (int)(rng() % 10);\n        vector<int> v(len);\n        int dom = (int)(rng() % 3);   // sometimes a dominant value exists\n        for (auto& x : v) x = (rng() % 3 == 0) ? (int)(rng() % 5) : dom;\n        if (cand(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
W["hsgx-p6-s3-majority"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <random>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    // WRONG candidate: Boyer-Moore WITHOUT verification \u2014 returns the\n    // residual candidate even when no majority exists (the classic trap).\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    mt19937 rng(2024);\n    auto cand = [](const vector<int>& v) {\n        int c = 0; int cand2 = 0;\n        for (int x : v) { if (c == 0) cand2 = x; c += (x == cand2) ? 1 : -1; }\n        return v.empty() ? -1 : cand2;   // BUG: no verification pass\n    };\n    auto brute = [](const vector<int>& v) {\n        for (int x : v) {\n            int cnt = 0;\n            for (int y : v) if (y == x) ++cnt;\n            if (2 * cnt > (int)v.size()) return x;\n        }\n        return -1;\n    };\n    const int TRIALS = 4000;\n    for (int t = 0; t < TRIALS; ++t) {\n        int len = (int)(rng() % 10);\n        vector<int> v(len);\n        int dom = (int)(rng() % 3);\n        for (auto& x : v) x = (rng() % 3 == 0) ? (int)(rng() % 5) : dom;\n        if (cand(v) != brute(v)) {\n            out << \"MISMATCH trial \" << t << \"\\n\";\n            return;\n        }\n    }\n    out << \"OK \" << TRIALS << \"\\n\";\n}\n";
