R["hsgx-p7-s1-pairmax"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    const long long MOD = 1000000007;\n    long long ans = 0;\n    for (long long i = 0; i < n; ++i) ans = (ans + (a[i] % MOD) * (i % MOD)) % MOD;\n    out << ans << \"\\n\";\n}\n";
W["hsgx-p7-s1-pairmax"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    const long long MOD = 1000000007;\n    long long ans = 0;\n    for (long long i = 0; i < n; ++i) ans = (ans + (a[i] % MOD) * (i % MOD)) % MOD;\n    out << ans << \"\\n\";\n}\n";
R["hsgx-p7-s2-window"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    deque<long long> dq;   // indices, increasing values\n    long long best = LLONG_MIN;\n    for (long long i = 0; i < n; ++i) {\n        while (!dq.empty() && a[dq.back()] >= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() <= i - k) dq.pop_front();\n        if (i >= k - 1) best = max(best, a[dq.front()]);\n    }\n    out << best << \"\\n\";\n}\n";
