R["hsgx-p8-b-subsetsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long best = 0;\n    long long bestd = -1;\n    for (long long m = 0; m < (1LL << n); ++m) {\n        long long s = 0;\n        for (long long i = 0; i < n; ++i)\n            if (m & (1LL << i)) s += a[i];\n        long long d = s > S ? s - S : S - s;\n        if (bestd < 0 || d < bestd || (d == bestd && s < best)) {\n            bestd = d; best = s;\n        }\n    }\n    out << best << \"\\n\";\n}";
W["hsgx-p8-b-subsetsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end(), greater<long long>());\n    long long r = 0;\n    for (long long x : a) if (r + x <= S) r += x;   // WRONG: greedy misses sums above S\n    out << r << \"\\n\";\n}";
R["hsgx-p8-c-coverage"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<pair<long long, long long>> ev;\n    ev.reserve(2 * n);\n    for (long long i = 0; i < n; ++i) {\n        long long l, r; in >> l >> r;\n        ev.push_back({l, 1});\n        ev.push_back({r + 1, -1});\n    }\n    sort(ev.begin(), ev.end());\n    long long cur = 0, best = 0;\n    for (auto& [x, d] : ev) {\n        cur += d;\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}";
W["hsgx-p8-c-coverage"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& [l, r] : v) in >> l >> r;\n    sort(v.begin(), v.end());\n    long long end = -1, cnt = 0;\n    for (auto& [l, r] : v) {\n        if (l > end) { ++cnt; end = r; }\n        else end = min(end, r);   // WRONG: chain logic, not overlap counting\n    }\n    out << cnt << \"\\n\";\n}";
R["hsgx-p8-d-pathxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, q; in >> n >> q;\n    vector<long long> a(n + 1);\n    for (long long i = 1; i <= n; ++i) in >> a[i];\n    bool star = true;\n    for (long long i = 0; i < n - 1; ++i) {\n        long long u, v; in >> u >> v;\n        if (u != 1 && v != 1) star = false;   // verify the shape, never assume it\n    }\n    for (long long t = 0; t < q; ++t) {\n        long long u, v; in >> u >> v;\n        long long ans;\n        if (u == v) ans = a[u];\n        else if (u == 1 || v == 1) ans = a[u] ^ a[v];\n        else ans = star ? (a[u] ^ a[1] ^ a[v]) : 0;   // non-star is out of scope by constraints; shape verified above\n        out << ans << \"\\n\";\n    }\n}";
W["hsgx-p8-d-pathxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <tuple>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, q; in >> n >> q;\n    vector<long long> a(n + 1);\n    for (long long i = 1; i <= n; ++i) in >> a[i];\n    vector<vector<long long>> adj(n + 1);\n    for (long long i = 0; i < n - 1; ++i) {\n        long long u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<long long> par(n + 1), order;\n    for (long long t = 0; t < q; ++t) {\n        long long u, v; in >> u >> v;\n        order.clear();\n        fill(par.begin(), par.end(), 0);\n        order.push_back(u);\n        par[u] = -1;\n        for (size_t h = 0; h < order.size() && !par[v]; ++h) {   // WRONG: O(n) BFS per query\n            long long x = order[h];\n            for (long long y : adj[x]) if (!par[y]) { par[y] = x; order.push_back(y); }\n        }\n        long long ans = 0;\n        for (long long z = v; z != -1; z = par[z]) ans ^= a[z];\n        out << ans << \"\\n\";\n    }\n}";
