R["hsgx-mc1-b-ropes"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    for (long long i = 0; i < n; ++i) {\n        long long x; in >> x;\n        pq.push(x);\n    }\n    long long total = 0;\n    while (pq.size() > 1) {\n        long long x = pq.top(); pq.pop();\n        long long y = pq.top(); pq.pop();\n        total += x + y;\n        pq.push(x + y);\n    }\n    out << total << \"\\n\";\n}";
W["hsgx-mc1-b-ropes"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    // WRONG: merges the two LARGEST first \u2014 the anti-greedy. Long merges\n    // should be rare and late; this pays them early and repeatedly.\n    priority_queue<long long> pq;\n    for (long long i = 0; i < n; ++i) {\n        long long x; in >> x;\n        pq.push(x);\n    }\n    long long total = 0;\n    while (pq.size() > 1) {\n        long long x = pq.top(); pq.pop();\n        long long y = pq.top(); pq.pop();\n        total += x + y;\n        pq.push(x + y);\n    }\n    out << total << \"\\n\";\n}";
R["hsgx-mc1-c-rangesum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, L, R; in >> n >> L >> R;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // For each running prefix s, count earlier prefixes p with\n    // s - R <= p <= s - L  (p includes the empty prefix 0).\n    vector<long long> pre(n + 1);\n    pre[0] = 0;\n    for (long long i = 0; i < n; ++i) pre[i + 1] = pre[i] + a[i];\n    vector<long long> vals;\n    for (long long i = 0; i <= n; ++i) {\n        vals.push_back(pre[i]);\n        vals.push_back(pre[i] - L);\n        vals.push_back(pre[i] - R);\n    }\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    vector<long long> bit(vals.size() + 2, 0);\n    auto up = [&](long long i) { for (; i < (long long)bit.size(); i += i & (-i)) bit[i] += 1; };\n    auto qr = [&](long long i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; };\n    auto id = [&](long long v) {\n        return (long long)(lower_bound(vals.begin(), vals.end(), v) - vals.begin()) + 1;\n    };\n    long long ans = 0;\n    up(id(0));\n    for (long long i = 1; i <= n; ++i) {\n        long long lo = id(pre[i] - R);\n        long long hi = id(pre[i] - L);\n        ans += qr(hi) - qr(lo - 1);\n        up(id(pre[i]));\n    }\n    out << ans << \"\\n\";\n}";
W["hsgx-mc1-c-rangesum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, L, R; in >> n >> L >> R;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: breaks the inner scan as soon as the window sum exceeds R \u2014\n    // with negative values a later window can dip back into [L, R].\n    long long ans = 0;\n    for (long long i = 0; i < n; ++i) {\n        long long s = 0;\n        for (long long j = i; j < n; ++j) {\n            s += a[j];\n            if (s > R) break;\n            if (s >= L) ++ans;\n        }\n    }\n    out << ans << \"\\n\";\n}";
R["hsgx-mc2-a-connect"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<long long> par(n + 1);\n    for (long long i = 1; i <= n; ++i) par[i] = i;\n    function<long long(long long)> find = [&](long long x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    long long comp = n;\n    for (long long e = 0; e < m; ++e) {\n        long long u, v; in >> u >> v;\n        long long ru = find(u), rv = find(v);\n        if (ru != rv) { par[rv] = ru; --comp; }\n        out << comp << \"\\n\";\n    }\n}";
W["hsgx-mc2-a-connect"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<long long> par(n + 1);\n    for (long long i = 1; i <= n; ++i) par[i] = i;\n    // WRONG: decrements the counter even when u and v were already in the\n    // same component \u2014 every redundant edge undercounts.\n    long long comp = n;\n    for (long long e = 0; e < m; ++e) {\n        long long u, v; in >> u >> v;\n        while (par[u] != u) u = par[u];\n        while (par[v] != v) v = par[v];\n        par[v] = u;\n        --comp;\n        out << comp << \"\\n\";\n    }\n}";
R["hsgx-mc2-b-dagpath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<vector<long long>> adj(n + 1);\n    vector<long long> indeg(n + 1, 0);\n    for (long long i = 0; i < m; ++i) {\n        long long u, v; in >> u >> v;\n        adj[u].push_back(v);\n        ++indeg[v];\n    }\n    vector<long long> dp(n + 1, 0);\n    queue<long long> q;\n    for (long long i = 1; i <= n; ++i) if (indeg[i] == 0) q.push(i);\n    long long best = 0;\n    while (!q.empty()) {\n        long long u = q.front(); q.pop();\n        for (long long v : adj[u]) {\n            if (dp[u] + 1 > dp[v]) dp[v] = dp[u] + 1;\n            if (dp[v] > best) best = dp[v];\n            if (--indeg[v] == 0) q.push(v);\n        }\n    }\n    out << best << \"\\n\";\n}";
W["hsgx-mc2-b-dagpath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<vector<long long>> adj(n + 1);\n    for (long long i = 0; i < m; ++i) {\n        long long u, v; in >> u >> v;\n        adj[u].push_back(v);\n    }\n    // WRONG: memo-free DFS counts VERTICES (seeds at len 1 and adds 1 per\n    // edge) \u2014 a path of k edges reports k+1 \u2014 and it is exponential on\n    // chains. The diamond sample fails immediately.\n    long long best = 0;\n    function<void(long long, long long)> dfs = [&](long long u, long long len) {\n        if (len > best) best = len;\n        for (long long v : adj[u]) dfs(v, len + 1);\n    };\n    for (long long i = 1; i <= n; ++i) dfs(i, 1);\n    out << best << \"\\n\";\n}";
R["hsgx-mc2-c-discount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<array<long long,3>> edges(m);\n    vector<vector<pair<long long,long long>>> adj(n + 1);\n    for (auto& e : edges) {\n        in >> e[0] >> e[1] >> e[2];\n        adj[e[0]].push_back({e[1], e[2]});\n        adj[e[1]].push_back({e[0], e[2]});\n    }\n    auto dij = [&](long long src) {\n        vector<long long> dist(n + 1, LLONG_MAX);\n        priority_queue<pair<long long,long long>, vector<pair<long long,long long>>, greater<>> pq;\n        dist[src] = 0;\n        pq.push({0, src});\n        while (!pq.empty()) {\n            auto [d, u] = pq.top(); pq.pop();\n            if (d != dist[u]) continue;\n            for (auto [v, w] : adj[u]) {\n                if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }\n            }\n        }\n        return dist;\n    };\n    // Both passes use RAW weights: the coupon is spent on exactly one edge,\n    // spliced in per-candidate \u2014 d1[u] + w/2 + dn[v] (undirected \u21d2 dn[v] is\n    // the true v\u2192n raw distance).\n    vector<long long> d1 = dij(1);\n    vector<long long> dn = dij(n);\n    long long ans = d1[n];\n    for (auto& e : edges) {\n        long long u = e[0], v = e[1], w = e[2];\n        if (d1[u] != LLONG_MAX && dn[v] != LLONG_MAX)\n            ans = min(ans, d1[u] + w / 2 + dn[v]);\n        if (d1[v] != LLONG_MAX && dn[u] != LLONG_MAX)\n            ans = min(ans, d1[v] + w / 2 + dn[u]);\n    }\n    out << ans << \"\\n\";\n}";
W["hsgx-mc2-c-discount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, m; in >> n >> m;\n    vector<vector<pair<long long,long long>>> adj(n + 1);\n    for (long long i = 0; i < m; ++i) {\n        long long u, v, w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    // WRONG: plain Dijkstra \u2014 never spends the coupon. Fails every test\n    // where the discount actually helps (with w \u2265 1 it always does).\n    vector<long long> dist(n + 1, LLONG_MAX);\n    priority_queue<pair<long long,long long>, vector<pair<long long,long long>>, greater<>> pq;\n    dist[1] = 0; pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto [v, w] : adj[u]) {\n            if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }\n        }\n    }\n    out << dist[n] << \"\\n\";\n}";
