R["hsgx-p3-windows"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long cnt = 0, s = 0;\n    int l = 0;\n    for (int r = 0; r < n; ++r) {\n        s += a[r];\n        while (s - a[l] >= S && l <= r) { s -= a[l]; ++l; }\n        if (s >= S) cnt += l + 1;  // windows [j..r], j = 0..l\n    }\n    out << cnt << \"\\n\";\n}\n";
W["hsgx-p3-windows"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: counts subarrays with sum == S exactly (misread \"at least\"),\n    // via running sums \u2014 plausible-looking, deterministic wrong answer.\n    long long cnt = 0, s = 0;\n    for (int r = 0; r < n; ++r) {\n        s = 0;\n        for (int l = r; l >= 0; --l) {\n            s += a[l];\n            if (s == S) ++cnt;\n        }\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsgx-p4-loadsplit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long lo = *max_element(a.begin(), a.end());\n    long long hi = 0;\n    for (long long x : a) hi += x;\n    while (lo < hi) {\n        long long mid = (lo + hi) / 2;\n        long long need = 1, cur = 0;\n        for (long long x : a) {\n            if (cur + x > mid) { ++need; cur = x; }\n            else cur += x;\n        }\n        if (need <= k) hi = mid; else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}\n";
W["hsgx-p4-loadsplit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: greedy \"start a new chunk when the current chunk exceeds the\n    // average\" \u2014 the average is not the answer; deterministic wrong output.\n    long long tot = 0;\n    for (long long x : a) tot += x;\n    long long avg = tot / max(1, k);\n    long long need = 1, cur = 0, best = 0;\n    for (long long x : a) {\n        if (cur + x > avg) { best = max(best, cur); ++need; cur = x; }\n        else cur += x;\n    }\n    best = max(best, cur);\n    out << best << \"\\n\";\n}\n";
R["hsgx-p3-uniquelen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = (int)s.size();\n    vector<int> last(256, -1);\n    int best = 0, l = 0;\n    for (int r = 0; r < n; ++r) {\n        if (last[(unsigned char)s[r]] >= l) l = last[(unsigned char)s[r]] + 1;\n        last[(unsigned char)s[r]] = r;\n        best = max(best, r - l + 1);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgx-p3-uniquelen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    // WRONG: tracks the current run length, resetting only on ADJACENT\n    // repeats. Misses non-adjacent duplicates (\"abcabc\" has no adjacent\n    // repeat, so the run grows to 6 \u2014 but the true longest unique window\n    // is 3). Deterministic wrong on the classic test and on the big one.\n    int n = (int)s.size();\n    int len = 0, best = 0;\n    for (int r = 0; r < n; ++r) {\n        if (r > 0 && s[r] == s[r - 1]) len = 1;\n        else ++len;\n        best = max(best, len);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgx-cp-m3-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long d; in >> n >> d;\n    vector<long long> cnt(d, 0);\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        ++cnt[((x % d) + d) % d];\n    }\n    long long pairs = cnt[0] * (cnt[0] - 1) / 2;\n    for (long long r = 1; r * 2 < d; ++r) pairs += cnt[r] * cnt[d - r];\n    if (d % 2 == 0) pairs += cnt[d / 2] * (cnt[d / 2] - 1) / 2;\n    out << pairs << \"\\n\";\n}\n";
W["hsgx-cp-m3-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long d; in >> n >> d;\n    vector<long long> cnt(d, 0);\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        ++cnt[((x % d) + d) % d];\n    }\n    // WRONG: counts ordered index pairs (i < j) as cnt[r] * cnt[d-r] for ALL\n    // r \u2014 double-counting every complementary pair {r, d-r} AND forgetting\n    // that self-paired residues need combinations, not products. Overcounts\n    // on every multi-residue test.\n    long long pairs = cnt[0] * (cnt[0] - 1) / 2;\n    for (long long r = 1; r < d; ++r) pairs += cnt[r] * cnt[d - r];\n    out << pairs << \"\\n\";\n}\n";
R["hsgx-p4-place"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long lo = 1, hi = a[n - 1] - a[0];\n    while (lo < hi) {\n        long long mid = (lo + hi + 1) / 2;\n        long long cnt = 1, last = a[0];\n        for (int i = 1; i < n && cnt < k; ++i) {\n            if (a[i] - last >= mid) { ++cnt; last = a[i]; }\n        }\n        if (cnt >= k) lo = mid; else hi = mid - 1;\n    }\n    out << lo << \"\\n\";\n}\n";
W["hsgx-p4-place"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    // WRONG: average-gap heuristic \u2014 place k points at equal average spacing.\n    // Deterministically wrong on clustered inputs.\n    long long span = a[n - 1] - a[0];\n    long long ans = span / max(1, k - 1);\n    out << ans << \"\\n\";\n}\n";
R["hsgx-p4-dominating"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> vals;\n    vals.reserve(2 * n);\n    for (long long x : a) { vals.push_back(x); vals.push_back(2 * x); }\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    auto rank = [&](long long v) {\n        return lower_bound(vals.begin(), vals.end(), v) - vals.begin() + 1;\n    };\n    int m = (int)vals.size();\n    vector<int> bit(m + 1, 0);\n    auto upd = [&](int i) { for (; i <= m; i += i & -i) bit[i]++; };\n    auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };\n    long long cnt = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        // inserted j > i: count values 2*a[j] strictly below a[i]\n        cnt += qry(rank(a[i]) - 1);\n        upd(rank(2 * a[i]));\n    }\n    out << cnt << \"\\n\";\n}\n";
W["hsgx-p4-dominating"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: O(n^2) nested scan \u2014 same answers, times out at n = 200000.\n    // The combination (compression + Fenwick) is the whole point.\n    long long cnt = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = i + 1; j < n; ++j)\n            if (a[i] > 2 * a[j]) ++cnt;\n    out << cnt << \"\\n\";\n}\n";
R["hsgx-p4-roads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> par(n + 1), sz(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    // iterative find (path halving)\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    int comp = n;\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        int ru = find(u), rv = find(v);\n        if (ru != rv) {\n            if (sz[ru] < sz[rv]) swap(ru, rv);\n            par[rv] = ru;\n            sz[ru] += sz[rv];\n            --comp;\n        }\n        out << comp << \"\\n\";\n    }\n}\n";
W["hsgx-p4-roads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    // WRONG: BFS the whole graph after each road \u2014 correct answers but\n    // O(n\u00b7m) \u2248 2\u00b710^10 at full scale; DSU over time is the point.\n    vector<vector<int>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n        vector<int> vis(n + 1, 0);\n        int comp = 0;\n        for (int s = 1; s <= n; ++s) {\n            if (vis[s]) continue;\n            ++comp;\n            vector<int> st = {s};\n            vis[s] = 1;\n            while (!st.empty()) {\n                int x = st.back(); st.pop_back();\n                for (int y : g[x]) if (!vis[y]) { vis[y] = 1; st.push_back(y); }\n            }\n        }\n        out << comp << \"\\n\";\n    }\n}\n";
R["hsgx-p4-parity"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<pair<int,int>>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v, w; in >> u >> v >> w;\n        g[u].push_back({v, w});\n        g[v].push_back({u, w});\n    }\n    // state: (vertex, parity of edges used). Min edges-walk with even count.\n    const long long INF = 1e18;\n    vector<vector<long long>> dist(n + 1, vector<long long>(2, INF));\n    priority_queue<tuple<long long,int,int>, vector<tuple<long long,int,int>>, greater<>> pq;\n    dist[1][0] = 0;\n    pq.push({0, 1, 0});\n    while (!pq.empty()) {\n        auto [d, u, p] = pq.top(); pq.pop();\n        if (d != dist[u][p]) continue;\n        for (auto [v, w] : g[u]) {\n            int np = p ^ 1;\n            if (d + w < dist[v][np]) {\n                dist[v][np] = d + w;\n                pq.push({d + w, v, np});\n            }\n        }\n    }\n    long long ans = dist[n][0];\n    out << (ans >= INF ? -1 : ans) << \"\\n\";\n}\n";
W["hsgx-p4-parity"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<pair<int,int>>> g(n + 1);\n    for (int e = 0; e < m; ++e) {\n        int u, v, w; in >> u >> v >> w;\n        g[u].push_back({v, w});\n        g[v].push_back({u, w});\n    }\n    // WRONG: plain Dijkstra from 1 to n ignoring parity \u2014 the classic\n    // non-state solution. Fails whenever the shortest walk has odd length.\n    const long long INF = 1e18;\n    vector<long long> dist(n + 1, INF);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto [v, w] : g[u]) {\n            if (d + w < dist[v]) { dist[v] = d + w; pq.push({d + w, v}); }\n        }\n    }\n    out << (dist[n] >= INF ? -1 : dist[n]) << \"\\n\";\n}\n";
R["hsgx-p5-coins"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // Tarjan SCC (iterative)\n    vector<int> low(n + 1), num(n + 1, 0), comp(n + 1, -1);\n    vector<int> stk, path;\n    vector<vector<int>> chains(n + 1);\n    vector<size_t> it(n + 1, 0);\n    int timer = 0, ncomp = 0;\n    for (int s = 1; s <= n; ++s) {\n        if (num[s]) continue;\n        path.push_back(s);\n        while (!path.empty()) {\n            int u = path.back();\n            if (it[u] == 0) { num[u] = low[u] = ++timer; stk.push_back(u); }\n            bool advanced = false;\n            while (it[u] < g[u].size()) {\n                int v = g[u][it[u]++];\n                if (!num[v]) { chains[u].push_back(v); path.push_back(v); advanced = true; break; }\n                else if (comp[v] < 0) low[u] = min(low[u], num[v]);\n            }\n            if (!advanced) {\n                if (low[u] == num[u]) {\n                    ++ncomp;\n                    while (true) {\n                        int v = stk.back(); stk.pop_back();\n                        comp[v] = ncomp;\n                        if (v == u) break;\n                    }\n                }\n                path.pop_back();\n                if (!path.empty()) {\n                    int p = path.back();\n                    low[p] = min(low[p], low[u]);\n                }\n            }\n        }\n    }\n    // condensation: total coins per comp + best DP in reverse topo (comp ids\n    // from Tarjan are already reverse-topological: edges go comp[u] -> comp[v]\n    // with comp[u] >= comp[v]... actually Tarjan numbers comps in reverse\n    // topological order of the condensation, so DP by increasing comp id over\n    // reversed edges)\n    vector<long long> tot(ncomp + 1, 0);\n    for (int v = 1; v <= n; ++v) tot[comp[v]] += coin[v];\n    vector<long long> best(ncomp + 1, 0);\n    vector<vector<int>> radj(ncomp + 1);\n    for (int u = 1; u <= n; ++u)\n        for (int v : g[u])\n            if (comp[u] != comp[v]) radj[comp[v]].push_back(comp[u]);\n    long long ans = 0;\n    // Tarjan numbers components in REVERSE topological order of the\n    // condensation (sinks get small ids). Edges go comp[u] -> comp[v] with\n    // comp[u] > comp[v] for distinct comps, so predecessors have HIGHER ids:\n    // DP must run by DESCENDING component id.\n    for (int c = ncomp; c >= 1; --c) {\n        best[c] = tot[c];\n        for (int p : radj[c]) best[c] = max(best[c], tot[c] + best[p]);\n        ans = max(ans, best[c]);\n    }\n    out << ans << \"\\n\";\n}\n";
W["hsgx-p5-coins"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // WRONG: longest-path DP on the raw graph assuming it is a DAG \u2014\n    // visits nodes multiple times / cycles inflate the count. The tests\n    // include cycles whose coins would be double-counted.\n    const long long NEG = -1e18;\n    vector<long long> best(n + 1, NEG);\n    // naive DFS without cycle handling, memoized as if DAG\n    vector<long long> memo(n + 1, -1);\n    function<long long(int)> dfs = [&](int u) -> long long {\n        if (memo[u] != -1) return memo[u];\n        long long r = coin[u];\n        for (int v : g[u]) r = max(r, coin[u] + dfs(v));\n        return memo[u] = r;\n    };\n    long long ans = 0;\n    for (int s = 1; s <= n; ++s) ans = max(ans, dfs(s));\n    out << ans << \"\\n\";\n}\n";
R["hsgx-cp-m4-coinroads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // Tarjan SCC (iterative)\n    vector<int> low(n + 1), num(n + 1, 0), comp(n + 1, -1);\n    vector<int> stk, path;\n    vector<vector<int>> chains(n + 1);\n    vector<size_t> it(n + 1, 0);\n    int timer = 0, ncomp = 0;\n    for (int s = 1; s <= n; ++s) {\n        if (num[s]) continue;\n        path.push_back(s);\n        while (!path.empty()) {\n            int u = path.back();\n            if (it[u] == 0) { num[u] = low[u] = ++timer; stk.push_back(u); }\n            bool advanced = false;\n            while (it[u] < g[u].size()) {\n                int v = g[u][it[u]++];\n                if (!num[v]) { chains[u].push_back(v); path.push_back(v); advanced = true; break; }\n                else if (comp[v] < 0) low[u] = min(low[u], num[v]);\n            }\n            if (!advanced) {\n                if (low[u] == num[u]) {\n                    ++ncomp;\n                    while (true) {\n                        int v = stk.back(); stk.pop_back();\n                        comp[v] = ncomp;\n                        if (v == u) break;\n                    }\n                }\n                path.pop_back();\n                if (!path.empty()) {\n                    int p = path.back();\n                    low[p] = min(low[p], low[u]);\n                }\n            }\n        }\n    }\n    // condensation: total coins per comp + best DP in reverse topo (comp ids\n    // from Tarjan are already reverse-topological: edges go comp[u] -> comp[v]\n    // with comp[u] >= comp[v]... actually Tarjan numbers comps in reverse\n    // topological order of the condensation, so DP by increasing comp id over\n    // reversed edges)\n    vector<long long> tot(ncomp + 1, 0);\n    for (int v = 1; v <= n; ++v) tot[comp[v]] += coin[v];\n    vector<long long> best(ncomp + 1, 0);\n    vector<vector<int>> radj(ncomp + 1);\n    for (int u = 1; u <= n; ++u)\n        for (int v : g[u])\n            if (comp[u] != comp[v]) radj[comp[v]].push_back(comp[u]);\n    long long ans = 0;\n    // Tarjan numbers components in REVERSE topological order of the\n    // condensation (sinks get small ids). Edges go comp[u] -> comp[v] with\n    // comp[u] > comp[v] for distinct comps, so predecessors have HIGHER ids:\n    // DP must run by DESCENDING component id.\n    for (int c = ncomp; c >= 1; --c) {\n        best[c] = tot[c];\n        for (int p : radj[c]) best[c] = max(best[c], tot[c] + best[p]);\n        ans = max(ans, best[c]);\n    }\n    out << ans << \"\\n\";\n}\n";
W["hsgx-cp-m4-coinroads"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <queue>\n#include <map>\n#include <set>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    vector<long long> coin(n + 1, 0);\n    for (int i = 1; i <= n; ++i) in >> coin[i];\n    for (int e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // WRONG: longest-path DP on the raw graph assuming it is a DAG \u2014\n    // visits nodes multiple times / cycles inflate the count. The tests\n    // include cycles whose coins would be double-counted.\n    const long long NEG = -1e18;\n    vector<long long> best(n + 1, NEG);\n    // naive DFS without cycle handling, memoized as if DAG\n    vector<long long> memo(n + 1, -1);\n    function<long long(int)> dfs = [&](int u) -> long long {\n        if (memo[u] != -1) return memo[u];\n        long long r = coin[u];\n        for (int v : g[u]) r = max(r, coin[u] + dfs(v));\n        return memo[u] = r;\n    };\n    long long ans = 0;\n    for (int s = 1; s <= n; ++s) ans = max(ans, dfs(s));\n    out << ans << \"\\n\";\n}\n";
R["hsgx-f1-showcase"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    map<long long, long long> cnt;\n    long long distinct = 0, s = 0, best = 0, l = 0;\n    for (long long r = 0; r < n; ++r) {\n        if (cnt[a[r]]++ == 0) ++distinct;\n        s += a[r];\n        while (distinct > k) {\n            if (--cnt[a[l]] == 0) --distinct;\n            s -= a[l];\n            ++l;\n        }\n        best = max(best, s);\n    }\n    out << best << \"\\n\";\n}";
W["hsgx-f1-showcase"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, k; in >> n >> k;\n    // WRONG: reads the window as holding at most k ELEMENTS (a plain max\n    // over length-k windows) \u2014 the distinctness constraint goes unseen.\n    // Fails the distinct trap: whole array has 2 distinct values (sum 12)\n    // but this stops after 6.\n    vector<long long> a(n), pre(n + 1, 0);\n    for (long long i = 0; i < n; ++i) { long long x; in >> x; a[i] = x; pre[i + 1] = pre[i] + x; }\n    long long best = 0;\n    for (long long i = k; i <= n; ++i) best = max(best, pre[i] - pre[i - k]);\n    out << best << \"\\n\";\n}";
R["hsgx-f2-chains"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    long long depth = 0, matched = 0;\n    for (char c : s) {\n        if (c == '(') ++depth;\n        else if (depth > 0) { --depth; ++matched; }\n    }\n    out << 2 * matched << \"\\n\";\n}";
W["hsgx-f2-chains"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    // WRONG: counts 2\u00b7min(opens, closes) \u2014 position-blind. A ')' before any\n    // '(' can never be matched; the order trap below exposes it.\n    long long opens = 0, closes = 0;\n    for (char c : s) (c == '(' ? opens : closes)++;\n    out << 2 * min(opens, closes) << \"\\n\";\n}";
R["hsgx-f3-painters"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, k; in >> n >> k;\n    vector<long long> a(n);\n    long long lo = 0, hi = 0;\n    for (auto& x : a) { in >> x; hi += x; lo = max(lo, x); }\n    auto ok = [&](long long cap) {\n        long long blocks = 1, s = 0;\n        for (long long x : a) {\n            if (s + x > cap) { ++blocks; s = x; }\n            else s += x;\n        }\n        return blocks <= k;\n    };\n    while (lo < hi) {\n        long long mid = lo + (hi - lo) / 2;\n        if (ok(mid)) hi = mid;\n        else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}";
W["hsgx-f3-painters"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n, k; in >> n >> k;\n    // WRONG: splits into k blocks of nearly EQUAL COUNT (n/k boards each) \u2014\n    // ignores the values, fails whenever values are uneven.\n    long long per = (n + k - 1) / k;\n    long long best = 0, i = 0;\n    for (long long b = 0; b < k; ++b) {\n        long long s = 0;\n        for (long long j = 0; j < per && i < n; ++j, ++i) { long long x; in >> x; s += x; }\n        best = max(best, s);\n    }\n    out << best << \"\\n\";\n}";
R["hsgx-f4-deadlines"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& [t, d] : v) in >> t >> d;\n    sort(v.begin(), v.end(), [](const auto& A, const auto& B) { return A.second < B.second; });\n    long long time = 0, worst = 0;\n    for (auto& [t, d] : v) {\n        time += t;\n        worst = max(worst, time - d);\n    }\n    out << worst << \"\\n\";\n}";
W["hsgx-f4-deadlines"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<pair<long long, long long>> v(n);\n    for (auto& [t, d] : v) in >> t >> d;\n    // WRONG: shortest job first \u2014 the classic anti-optimality for max\n    // lateness; a short job with a far deadline jumps ahead of a long job\n    // with a near deadline and detonates the long one's lateness.\n    sort(v.begin(), v.end());\n    long long time = 0, worst = 0;\n    for (auto& [t, d] : v) {\n        time += t;\n        worst = max(worst, time - d);\n    }\n    out << worst << \"\\n\";\n}";
R["hsgx-f5-lucky"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string N; in >> N;\n    long long dp[2][7] = {};\n    dp[1][0] = 1;   // tight, empty prefix, mod 0\n    for (char c : N) {\n        int d = c - '0';\n        long long ndp[2][7] = {};\n        for (int tight = 0; tight < 2; ++tight)\n            for (int m = 0; m < 7; ++m) {\n                long long cur = dp[tight][m];\n                if (!cur) continue;\n                int lim = tight ? d : 9;\n                for (int dig = 0; dig <= lim; ++dig) {\n                    int nt = (tight && dig == lim) ? 1 : 0;\n                    ndp[nt][(m + dig) % 7] += cur;\n                }\n            }\n        for (int t = 0; t < 2; ++t)\n            for (int m = 0; m < 7; ++m) dp[t][m] = ndp[t][m];\n    }\n    long long ans = dp[0][0] + dp[1][0] - 1;   // exclude x = 0\n    out << ans << \"\\n\";\n}";
W["hsgx-f5-lucky"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string N; in >> N;\n    long long dp[2][7] = {};\n    dp[1][0] = 1;\n    for (char c : N) {\n        int d = c - '0';\n        long long ndp[2][7] = {};\n        for (int tight = 0; tight < 2; ++tight)\n            for (int m = 0; m < 7; ++m) {\n                long long cur = dp[tight][m];\n                if (!cur) continue;\n                int lim = tight ? d : 9;\n                for (int dig = 0; dig <= lim; ++dig) {\n                    int nt = (tight && dig == lim) ? 1 : 0;\n                    ndp[nt][(m + dig) % 7] += cur;\n                }\n            }\n        for (int t = 0; t < 2; ++t)\n            for (int m = 0; m < 7; ++m) dp[t][m] = ndp[t][m];\n    }\n    // WRONG: forgets to subtract x = 0 \u2014 the empty number has digit sum 0,\n    // which the DP counts as divisible; every answer is exactly one too big.\n    out << dp[0][0] + dp[1][0] << \"\\n\";\n}";
R["hsgx-f6-bookings"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<array<long long, 3>> v(n);\n    for (auto& x : v) in >> x[0] >> x[1] >> x[2];\n    sort(v.begin(), v.end(), [](const auto& A, const auto& B) { return A[1] < B[1]; });\n    vector<long long> ends(n);\n    for (long long i = 0; i < n; ++i) ends[i] = v[i][1];\n    vector<long long> dp(n + 1, 0);\n    for (long long i = 1; i <= n; ++i) {\n        long long s = v[i - 1][0], w = v[i - 1][2];\n        long long j = (long long)(upper_bound(ends.begin(), ends.begin() + i - 1, s) - ends.begin());\n        dp[i] = max(dp[i - 1], dp[j] + w);\n    }\n    out << dp[n] << \"\\n\";\n}";
W["hsgx-f6-bookings"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<array<long long, 3>> v(n);\n    for (auto& x : v) in >> x[0] >> x[1] >> x[2];\n    // WRONG: greedy by weight \u2014 the heaviest booking first, compatible or\n    // not afterwards. A heavy middle booking can block two medium ones that\n    // jointly pay more.\n    sort(v.begin(), v.end(), [](const auto& A, const auto& B) { return A[2] > B[2]; });\n    vector<array<long long, 2>> taken;\n    long long total = 0;\n    for (auto& [s, e, w] : v) {\n        bool ok = true;\n        for (auto& [ts, te] : taken)\n            if (s < te && ts < e) { ok = false; break; }\n        if (ok) { taken.push_back({s, e}); total += w; }\n    }\n    out << total << \"\\n\";\n}";
R["hsgx-cp-m12-drone"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<vector<long long>> g(n, vector<long long>(n));\n    for (auto& row : g) for (auto& x : row) in >> x;\n    const long long NEG = LLONG_MIN / 4;\n    // dp[used][j]: max sum reaching column j of the current row with\n    // `used` = 0/1 discards spent. Rolled over row by row.\n    vector<vector<long long>> dp0(n, vector<long long>(n, NEG));\n    vector<vector<long long>> dp1(n, vector<long long>(n, NEG));\n    dp0[0][0] = g[0][0];\n    dp1[0][0] = 0;   // discard the start cell's haul\n    for (long long i = 0; i < n; ++i) {\n        for (long long j = 0; j < n; ++j) {\n            if (i == 0 && j == 0) continue;\n            long long bf = NEG, bu = NEG;\n            if (i > 0) { bf = max(bf, dp0[i - 1][j]); bu = max(bu, dp1[i - 1][j]); }\n            if (j > 0) { bf = max(bf, dp0[i][j - 1]); bu = max(bu, dp1[i][j - 1]); }\n            if (bf == NEG) { dp0[i][j] = NEG; dp1[i][j] = NEG; continue; }\n            dp0[i][j] = bf + g[i][j];\n            dp1[i][j] = max(bu + g[i][j], bf);   // spend the discard here\n        }\n    }\n    out << max(dp0[n - 1][n - 1], dp1[n - 1][n - 1]) << \"\\n\";\n}";
W["hsgx-cp-m12-drone"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <utility>\n#include <map>\n#include <set>\n#include <tuple>\n#include <queue>\n#include <functional>\n#include <climits>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long n; in >> n;\n    vector<vector<long long>> g(n, vector<long long>(n));\n    for (auto& row : g) for (auto& x : row) in >> x;\n    // WRONG: computes the plain best path, then subtracts the globally most\n    // negative cell \u2014 even when that cell is not on the path at all.\n    long long best = LLONG_MIN, gmin = 0;\n    for (long long i = 0; i < n; ++i)\n        for (long long j = 0; j < n; ++j) gmin = min(gmin, g[i][j]);\n    vector<vector<long long>> dp(n, vector<long long>(n, LLONG_MIN));\n    dp[0][0] = g[0][0];\n    for (long long i = 0; i < n; ++i)\n        for (long long j = 0; j < n; ++j) {\n            if (i == 0 && j == 0) continue;\n            long long bf = LLONG_MIN;\n            if (i > 0) bf = max(bf, dp[i - 1][j]);\n            if (j > 0) bf = max(bf, dp[i][j - 1]);\n            dp[i][j] = bf + g[i][j];\n        }\n    best = dp[n - 1][n - 1];\n    if (gmin < 0) best -= gmin;\n    out << best << \"\\n\";\n}";
